{
  "clusters": [
    {
      "cluster_id": "C1",
      "label": "The Pub as an Effortless and Default Social Venue",
      "definition": "The pub serves as the default, primary, and highly convenient meeting space because it is familiar, low-barrier, and requires no advance planning or active coordination."
    },
    {
      "cluster_id": "C2",
      "label": "Comfort and Belonging of Familiar Spaces",
      "definition": "Consistently visiting a familiar local venue builds trust and a sense of belonging, allowing participants to feel accepted and be themselves without social pressure."
    },
    {
      "cluster_id": "C3",
      "label": "Sticking to a Default Venue to Avoid Coordination",
      "definition": "Choosing a single default spot simplifies organizing get-togethers and eliminates the friction, decision-making, and negotiation of coordinating multiple options."
    },
    {
      "cluster_id": "C4",
      "label": "Masculinity and the Social Policing of Meat Eating",
      "definition": "Dietary choices, particularly reducing or avoiding meat, are often policed or met with scrutiny in male social circles where meat consumption is tied to expectations of masculinity."
    },
    {
      "cluster_id": "C5",
      "label": "Value of Gathering in Private and Home Settings",
      "definition": "Hanging out in private spaces, like homes or gardens, is valued as a comfortable, cost-effective, and low-pressure alternative to public venues that fosters deeper conversations."
    },
    {
      "cluster_id": "C6",
      "label": "Balancing Friendships with Adult Life Responsibilities",
      "definition": "Maintaining regular social contact with friends becomes challenging due to career and family commitments, requiring groups to actively adapt the timing and format of their gatherings."
    },
    {
      "cluster_id": "C7",
      "label": "Erosion of Spontaneous Connection due to Venue Closures",
      "definition": "The closure of local neighborhood social spaces disrupts spontaneous socializing, forces friends to shift to pre-scheduled events, and damages community connection."
    },
    {
      "cluster_id": "C8",
      "label": "Value of Quiet Settings for Conversation",
      "definition": "Friends prefer atmospheric, moderately quiet dining or drinking environments where they can easily hear each other and engage in comfortable conversation without background noise."
    },
    {
      "cluster_id": "C9",
      "label": "Geographic Setting and Infrastructure Shaping Socializing",
      "definition": "Geographical location dictates planning needs; regional or rural areas require more intentional scheduling around limited venues, whereas urban settings offer effortless, spontaneous options."
    },
    {
      "cluster_id": "C10",
      "label": "The Tension Between Choice Abundance and Social Connection",
      "definition": "Having too many venue choices can dilute deep community connections, whereas intentionally choosing or defaulting to limited options fosters closer bonds."
    },
    {
      "cluster_id": "C11",
      "label": "Sports as a Catalyst for Social Bonding",
      "definition": "Gathering around sports activities, whether active play, watching matches together, or meeting at sports clubs, provides a highly familiar and convenient social anchor."
    },
    {
      "cluster_id": "C12",
      "label": "Friendship as a Space to Escape Pressures and Be Authentic",
      "definition": "Spending time with close male friends offers a vital mental health release to escape daily responsibilities, shed professional or domestic roles, and communicate authentically."
    },
    {
      "cluster_id": "C13",
      "label": "Preference for Unpretentious and Low-Key Social Spaces",
      "definition": "Participants express a strong preference for everyday, low-key, and unpretentious environments where they can socialize casually without pretense or performance."
    },
    {
      "cluster_id": "C14",
      "label": "Navigating Community Scrutiny and Social Obligation",
      "definition": "Close-knit local communities offer support but also bring pressure, social obligation, and scrutiny, leading to a desire for a comfortable balance between visibility and anonymity."
    },
    {
      "cluster_id": "C15",
      "label": "Prioritizing Convenience and Affordability in Social Venues",
      "definition": "When deciding where to meet, participants prioritize establishments that offer affordable food and drink, or easily accessible locations near their daily routes."
    },
    {
      "cluster_id": "C16",
      "label": "Shifting Social Preferences in Older Age",
      "definition": "As participants grow older or retire, their social habits transition from automatic pub routines and heavy drinking toward quieter, more intentional gatherings centered on proper conversation."
    },
    {
      "cluster_id": "C17",
      "label": "The Shift to Intentional, Planned Socializing",
      "definition": "When circumstances like distance or busy lives prevent spontaneous catchups, friends rely on deliberate travel planning and digital coordination to maintain their bonds."
    },
    {
      "cluster_id": "C18",
      "label": "Increased Consciousness and Quality Standards for Food",
      "definition": "Men are increasingly paying attention to food sourcing and quality, particularly regarding meat, often leading to more conscious consumption and reduced red meat intake."
    }
  ],
