{
  "clusters": [
    {
      "cluster_id": "C1",
      "label": "Practicality and Convenience in Daily Food Choices",
      "definition": "Day-to-day eating decisions are driven primarily by habit, immediate convenience, cost, time constraints, and ease of preparation rather than active or deep planning."
    },
    {
      "cluster_id": "C2",
      "label": "Meat Consumption as an Unquestioned Default Habit",
      "definition": "Eating meat is treated as a routine, automatic, and unquestioned dietary choice shaped by upbringing and familiarity rather than active deliberation."
    },
    {
      "cluster_id": "C3",
      "label": "Spontaneous and Mood-Driven Meal Selections",
      "definition": "Food choices are made flexibly in the moment, relying on immediate appetite, cravings, and fluidly adapting to available ingredients rather than following a strict plan."
    },
    {
      "cluster_id": "C4",
      "label": "Commuting Disruptions and Fatigue as Barriers to Routine",
      "definition": "The physical exhaustion and unpredictability of long commutes deplete mental bandwidth, leading to decision fatigue, disrupted dining habits, and the abandonment of structured planning."
    },
    {
      "cluster_id": "C5",
      "label": "Tension Between Community Visibility and Urban Anonymity",
      "definition": "The social pressure and behavioral expectations of being recognized in a close community are contrasted with the freedom and lack of social performance offered by city anonymity."
    },
    {
      "cluster_id": "C6",
      "label": "Sourcing Food from Local Independent Suppliers",
      "definition": "Purchasing food from trusted local independent shops involves adapting to daily ingredient availability and navigating geographical constraints, fostering a deeper connection to food origins."
    },
    {
      "cluster_id": "C7",
      "label": "Reliance on Domestic Partners for Household Meal Planning",
      "definition": "The cognitive load and responsibility of structuring, planning, and managing daily household meals often falls primarily on one's partner, particularly wives."
    },
    {
      "cluster_id": "C8",
      "label": "Social Connection and Bonding Through Shared Meals",
      "definition": "Sharing a meal with others provides a meaningful, unhurried space for genuine conversation and social connection, contrasting with the isolation of eating alone."
    },
    {
      "cluster_id": "C9",
      "label": "Geographical Scale of Cities as a Barrier to Socializing",
      "definition": "The large physical size of urban environments and long commuting distances create significant temporal obstacles that discourage spontaneous, localized social routines."
    },
    {
      "cluster_id": "C10",
      "label": "Decline of Local Independent Shops and the Tension with Convenience",
      "definition": "The closure of traditional, independent local businesses and their replacement by corporate chains reduces authentic variety and highlights the tension between supporting local trade and supermarket convenience."
    },
    {
      "cluster_id": "C11",
      "label": "Familiarity and Community Recognition as Insufficient to Prevent Loneliness or Ensure Support",
      "definition": "Having established local routines and being well-known in a community does not guarantee active assistance during a crisis or prevent deep personal loneliness."
    },
    {
      "cluster_id": "C12",
      "label": "Retirement as a Catalyst for Re-structuring Daily Routines and Domestic Roles",
      "definition": "Retirement provides the time and mental space to step away from automatic work-related schedules, shifting domestic dynamics toward increased cooking, household participation, and the deliberate search for daily structure."
    },
    {
      "cluster_id": "C13",
      "label": "Age-Related Physical and Cognitive Shifts in Dietary Habits",
      "definition": "The process of aging prompts adjustments to food choices due to changing physical tolerances, decreased appetite, health concerns, and heightened awareness of food sources."
    },
    {
      "cluster_id": "C14",
      "label": "Financial Pressures of Rising Prices Driving Changes in Food Purchasing",
      "definition": "Increasing food costs, particularly for meat, force individuals to make practical budget adjustments or subtly shift their buying habits."
    },
    {
      "cluster_id": "C15",
      "label": "Social and Environmental Reinforcement of Traditional Dietary Norms for Men",
      "definition": "Men experience peer expectations, banter, and pub environments that implicitly perpetuate traditional eating habits and make alternative choices feel non-standard."
    },
    {
      "cluster_id": "C16",
      "label": "Expectations of Higher Quality and Relaxation When Dining Out",
      "definition": "Unlike casual home cooking where convenience is prioritized, dining out is valued for its superior food preparation, ingredient quality, and the opportunity to relax because someone else does the work."
    },
    {
      "cluster_id": "C17",
      "label": "Defaulting to and Finding Comfort in Familiar Routines",
      "definition": "Sticking to predictable, habitual choices for meals and social venues provides comfort and ease by eliminating the need for active decision-making."
    },
    {
      "cluster_id": "C18",
      "label": "Anxiety and Decision Paralysis Caused by an Abundance of Options",
      "definition": "Having an overwhelming excess of options, such as on delivery apps, leads to overthinking, constant self-doubt, and decision paralysis."
    }
  ],
