{
  "clusters": [
    {
      "cluster_id": "C1",
      "label": "Cultural Association of Meat with Masculinity",
      "definition": "Eating meat is deeply embedded as a primary cultural norm and default expectation for men, while lighter, vegetarian, or health-conscious diets are stereotypically associated with women."
    },
    {
      "cluster_id": "C2",
      "label": "Peer Pressure and Social Policing of Men's Diet",
      "definition": "Men face external social pressure, group banter, teasing, and internal self-policing to conform to hearty, meat-heavy diets and avoid lighter, vegetarian, or 'feminine' options in social settings."
    },
    {
      "cluster_id": "C3",
      "label": "Irrelevance of Gender to Food Choices",
      "definition": "Dietary choices are driven by personal preferences, health, and fitness goals rather than gender identity, which participants reject as a meaningful influence on their eating habits."
    },
    {
      "cluster_id": "C4",
      "label": "Wives Holding the Cognitive Burden of Food Planning",
      "definition": "Even when men contribute to cooking, their wives continue to carry the primary long-term, strategic mental load of grocery inventory, meal planning, and nutritional organization."
    },
    {
      "cluster_id": "C5",
      "label": "Upbringing and Routine Establishing Dietary Defaults",
      "definition": "Early childhood habits, family traditions, and regional upbringings normalize meat-eating as an unexamined, automatic default that does not require conscious reflection."
    },
    {
      "cluster_id": "C6",
      "label": "Rejection of Meat-Eating as a Performance of Masculinity",
      "definition": "Participants reject the traditional link between eating meat and manhood, characterizing meat consumption as a personal preference rather than an active performance or statement of masculinity."
    },
    {
      "cluster_id": "C7",
      "label": "Impact of Geographic Isolation on Food Planning",
      "definition": "Living in remote areas with limited retail choices and declining local stores forces individuals to engage in active, effortful food planning and management, disrupting automatic routines."
    },
    {
      "cluster_id": "C8",
      "label": "Heightened Social Scrutiny in Small Communities",
      "definition": "Residents of close-knit, small, or rural communities experience a lack of anonymity that heightens self-consciousness and the feeling of being judged or gossiped about for their food choices."
    },
    {
      "cluster_id": "C9",
      "label": "Social Familiarity Reducing Dietary Pressure",
      "definition": "The self-consciousness and pressure to conform to gendered food choices are mitigated when dining with familiar peers or in relaxed settings, but recur in unfamiliar or larger groups."
    },
    {
      "cluster_id": "C10",
      "label": "Debate Between Personal Agency and Social Conditioning",
      "definition": "There is an active debate and tension regarding whether eating behaviors represent authentic personal preference and choice or are instead products of internalized social expectations and automatic habit."
    },
    {
      "cluster_id": "C11",
      "label": "Alternative Diets as Loaded Ideological Statements",
      "definition": "Choosing vegetarianism or veganism is socially interpreted as making a conspicuous, politically or morally charged statement of identity, which invites scrutiny and social risk."
    },
    {
      "cluster_id": "C12",
      "label": "Privilege of Non-Reflection for Dietary Conformists",
      "definition": "Conformity to standard dietary practices affords individuals the luxury of eating without self-examination, whereas those who choose alternative diets must navigate constant calculations and social explanations."
    },
    {
      "cluster_id": "C13",
      "label": "Lack of Expectations and Skills for Men in Cooking and Nutrition",
      "definition": "Society has historically expected less from men regarding cooking and nutrition, leading to passive habits, convenience-reliance, and intergenerational patterns of non-cooking."
    },
    {
      "cluster_id": "C14",
      "label": "Expectation of Masculine Nonchalance and Non-Fussiness",
      "definition": "Men face social expectations to appear casual and indifferent about their eating, where being selective, overly invested in ingredients, or raising food concerns is viewed as fussy or unmasculine."
    },
    {
      "cluster_id": "C15",
      "label": "Gendered Categorization of Specific Foods",
      "definition": "Certain foods, such as salads, delicate dishes, or sweet/sugary foods, are culturally labeled as feminine, prompting men to avoid them to maintain their masculine identity."
    }
  ],
