{
  "clusters": [
    {
      "cluster_id": "C1",
      "label": "Unexamined Eating Habits and Resistance to Change",
      "definition": "Continuing with a standard meat-eating diet is driven by inertia, convenience, and a lack of active motivation or desire to change what is already comfortable and functioning well."
    },
    {
      "cluster_id": "C2",
      "label": "Practical and Logistical Disruption of Cooking Routines",
      "definition": "Transitioning to a plant-based diet is hindered by the practical effort required to disrupt established daily routines, learn new meal planning and recipe knowledge, and overhaul domestic kitchen habits."
    },
    {
      "cluster_id": "C3",
      "label": "Social Scrutiny and Labeling of Dietary Alternatives",
      "definition": "Adopting a plant-based diet is often perceived as a public, performative statement rather than a private choice, making individuals socially visible and subject to judgment, questioning, or permanent social labeling."
    },
    {
      "cluster_id": "C4",
      "label": "Masculine Identity and Social Peer Pressure around Meat Eating",
      "definition": "Standard food choices are heavily tied to culturally approved masculine identities, causing male peer groups to enforce conformity around eating meat and view departures from this norm as a threat to masculine self-image."
    },
    {
      "cluster_id": "C5",
      "label": "Influence of Lifelong Cultural Conditioning on Food Preferences",
      "definition": "Individual food choices and the perception of what constitutes a proper meal are deeply shaped by cultural upbringing and childhood social conditioning, making it difficult to distinguish genuine personal preference from internalized social norms."
    },
    {
      "cluster_id": "C6",
      "label": "Skepticism and Dislike of Processed Meat Alternatives",
      "definition": "Plant-based meat substitutes are viewed with skepticism or dislike due to perceived issues with taste, texture, transparency of ingredients, and high levels of food processing, with some preferring natural vegetables instead."
    },
    {
      "cluster_id": "C7",
      "label": "Relational Friction and Disruption of Family Routines",
      "definition": "Changing to a plant-based diet introduces cognitive planning burdens, potential friction, and disruption to established relationship dynamics and cooking routines shared with family members or domestic partners."
    },
    {
      "cluster_id": "C8",
      "label": "Personal Preference and Life Satisfaction in Eating Meat",
      "definition": "For some individuals, eating meat is a strong, active personal preference and a key source of daily enjoyment and life satisfaction rather than a passive habit."
    },
    {
      "cluster_id": "C9",
      "label": "Geographic and Structural Constraints on Food Access",
      "definition": "Practical obstacles such as living in remote or rural areas, limited shopping choices, and poor ingredient availability structurally constrain an individual's ability to transition to alternative diets."
    },
    {
      "cluster_id": "C10",
      "label": "Requirement of Major Catalysts or Health Issues to Change",
      "definition": "Transitioning to a plant-based diet would require severe, life-altering external triggers, such as serious health concerns, medical necessity, or major changes in relationship status, to overcome current habits."
    },
    {
      "cluster_id": "C11",
      "label": "Self-Censorship to Avoid Relationship Conflict",
      "definition": "Individuals may pre-emptively suppress their own preferences, thoughts, and food choices to manage their partners' reactions and maintain harmony, sometimes to the point of disappearing from domestic decision-making."
    },
    {
      "cluster_id": "C12",
      "label": "Passive Complicity in Sustaining Meat-Eating Norms",
      "definition": "By remaining silent, failing to challenge peer pressure, or simply going along with traditional eating habits, individuals passively participate in reinforcing and maintaining dominant societal dietary norms."
    },
    {
      "cluster_id": "C13",
      "label": "Age and Later-Life Comfort as Barriers to Disruption",
      "definition": "Older individuals often place high value on remaining content and settled with long-standing relationships and habits, making them less willing to disrupt comfortable life patterns to learn new dietary behaviors."
    },
    {
      "cluster_id": "C14",
      "label": "Meal Simplification as a Response to Living Alone",
      "definition": "For individuals living alone, particularly after a partnership, adopting simple or low-effort eating habits can be tied to feelings of loss, coping, or an active choice in response to their solitary circumstances."
    },
    {
      "cluster_id": "C15",
      "label": "Food Delivery Apps as a Retreat from Social Pressure",
      "definition": "Relying on food ordering apps allows individuals to bypass social anxieties and retreat into comfortable, invisible spaces, though this can foster long-term dependency and erode engagement with public spaces."
    },
    {
      "cluster_id": "C16",
      "label": "Intellectualization and External Excuses as Defense Mechanisms against Change",
      "definition": "Performing self-awareness, analyzing the reasons for not changing, or focusing heavily on external barriers can serve as defense mechanisms to avoid taking actual, messy action to change habits."
    },
    {
      "cluster_id": "C17",
      "label": "Cognitive Burden and Existential Loss of Automatic Routines",
      "definition": "Questioning long-held dietary habits and making conscious choices introduces an unwelcome cognitive burden, disrupting a hard-won sense of stability and the ease of acting automatically."
    },
    {
      "cluster_id": "C18",
      "label": "Friction and Exhaustion of Sustaining Habit Change",
      "definition": "Realizing lifestyle adjustments requires engaging with the messy, exhausting friction of everyday life, highlighting the tension between good intentions and the reality of breaking habits."
    },
    {
      "cluster_id": "C19",
      "label": "Prioritizing Relational Cooking over Abstract Dietary Adjustments",
      "definition": "Cooking to connect with, care for, and nurture family members is viewed as a more fundamental and urgent priority than experimenting with hypothetical dietary changes."
    },
    {
      "cluster_id": "C20",
      "label": "The Dual Strain of Logistical and Social Obstacles",
      "definition": "Transitioning to a plant-based diet is uniquely challenging because it simultaneously demands practical, logistical adaptations in daily preparation and navigating uncomfortable social friction with peers."
    },
    {
      "cluster_id": "C21",
      "label": "Financial and Price Barriers of Plant-Based Diets",
      "definition": "The higher cost of plant-based options compared to traditional meat-based foods presents a substantial economic barrier to adoption, particularly during a cost-of-living crisis."
    }
  ],
