{
  "clusters": [
    {
      "cluster_id": "C1",
      "label": "Disconnect Between Knowledge and Action",
      "definition": "Recognizing the need or benefit of dietary change intellectually is distinct from taking concrete action, creating a frustrating gap between awareness and behavior change."
    },
    {
      "cluster_id": "C2",
      "label": "Personal Motivators Over Abstract Concerns",
      "definition": "Abstract environmental or ethical arguments are generally insufficient to drive dietary change; individuals require direct, personal, and self-interested motivators such as health concerns or financial necessity to take action."
    },
    {
      "cluster_id": "C3",
      "label": "Normalization and Decoupling from Identity Signaling",
      "definition": "To achieve widespread appeal, plant-based food must be integrated quietly and casually into everyday menus and routines, stripping it of moralistic baggage, political statements, or alternative lifestyle signaling to remove social friction."
    },
    {
      "cluster_id": "C4",
      "label": "Comfort, Habit, and Contentment as Barriers to Change",
      "definition": "Deeply ingrained habits, a preference for familiar comfort foods, and general contentment with current eating patterns act as primary obstacles to reflecting on or adopting a plant-based diet."
    },
    {
      "cluster_id": "C5",
      "label": "Defensive Rationalization of Inaction",
      "definition": "Individuals often construct or focus heavily on external, environmental, or practical barriers as convenient excuses to justify inaction and avoid the effort or social discomfort of making an intentional choice."
    },
    {
      "cluster_id": "C6",
      "label": "Celebrating Plant-Based Foods on Their Own Terms",
      "definition": "Plant-based culinary options are more appealing when they embrace their own identity and are presented as hearty, naturally delicious dishes rather than trying to serve as disappointing, highly processed imitations of meat."
    },
    {
      "cluster_id": "C7",
      "label": "Affordability and Price Competitiveness",
      "definition": "Price is a critical factor in dietary choices; plant-based alternatives must achieve cost parity with meat and be affordable for everyday shopping to encourage adoption."
    },
    {
      "cluster_id": "C8",
      "label": "Sensory Realism of Meat Substitutes",
      "definition": "For meat eaters to consider transitioning to plant-based substitutes, replicating the exact flavor, texture, and overall sensory experience of eating real meat is essential."
    },
    {
      "cluster_id": "C9",
      "label": "Social and Contextual Shaping of Taste",
      "definition": "Food preferences are not innate or purely personal, but are instead socially constructed, conditioned since childhood, and sustained by environmental defaults and the lack of social friction."
    },
    {
      "cluster_id": "C10",
      "label": "Masculinity and Community Constraints",
      "definition": "Social expectations of male identity and regional or community norms frequently link meat-eating with masculinity, imposing structural and social barriers to adopting plant-based diets."
    },
    {
      "cluster_id": "C11",
      "label": "Domestic Dependency and Cooking Roles",
      "definition": "Dietary changes are constrained by traditional household roles, the mental burden of meal planning, and dependency on partners or spouses who primarily manage and prepare the household meals."
    },
    {
      "cluster_id": "C12",
      "label": "Ingredient Transparency and Skepticism of Highly Processed Alternatives",
      "definition": "Consumers exhibit hesitation and skepticism toward meat substitutes due to concerns about high levels of processing, artificial additives, salts, fats, and long, unfamiliar ingredient lists."
    },
    {
      "cluster_id": "C13",
      "label": "Social Friction and Visibility of Non-Conforming Choices",
      "definition": "Eating is a highly public and social activity, making any departure from the default of meat-eating highly visible and subject to uncomfortable peer commentary, teasing, and community enforcement of social norms."
    },
    {
      "cluster_id": "C14",
      "label": "Environmental Absence of Choice",
      "definition": "Lifestyle and dietary choices remain completely unconsidered rather than consciously rejected if they are entirely absent from an individual's immediate local environment, infrastructure, and social circles."
    },
    {
      "cluster_id": "C15",
      "label": "Culinary Education and Cooking Approachability",
      "definition": "Overcoming the perceived complexity of plant-based eating requires hands-on cooking experience, simple recipes, and clear ingredient education to make home-prepared meals feel accessible."
    },
    {
      "cluster_id": "C16",
      "label": "Meat-Eating as an Unquestioned Default",
      "definition": "Meat consumption is often sustained as an unexamined, habitual routine and daily autopilot behavior rather than being the result of a conscious, active choice."
    }
  ],
